import os,sys,pathlib,hashlib,base64,gzip,subprocess,mmap,fcntl,struct,json
assert os.uname().release=='5.4.0' and os.uname().machine=='aarch64'
config=gzip.decompress(pathlib.Path('/proc/config.gz').read_bytes()).decode()
assert '# CONFIG_MODVERSIONS is not set' in config
assert 'CONFIG_ARM_SMMU=y' not in config and 'CONFIG_ARM_SMMU=m' not in config, 'DMA path requires SMMU review'
required=['__arch_copy_to_user', 'dma_alloc_attrs', 'dma_free_attrs', 'dma_mmap_attrs', 'dma_set_coherent_mask', 'dma_set_mask', 'memset', 'misc_deregister', 'misc_register', 'no_llseek', 'nonseekable_open', 'param_ops_ulong', 'printk', '__stack_chk_fail']
symbols={ln.split()[-1] for ln in pathlib.Path('/proc/kallsyms').read_text().splitlines() if ln.split()}
missing=[x for x in required if x not in symbols]
print('VISIBLE_KERNEL_SYMBOL_CHECK',len(required),'missing',missing,flush=True)
assert set(missing)<= {'param_ops_ulong'} and (not missing or '# CONFIG_KALLSYMS_ALL is not set' in config), 'Required function symbols are missing'
# param_ops_ulong is a data export hidden when KALLSYMS_ALL is disabled.
# Normal insmod performs the authoritative export/relocation check; no force flags.
data=base64.b64decode('')
sha='13a403ddecd24d0e96af3bde8b7eda61c5f5e7894b4d0a07f9e2d0bf3e7ca0ab'
assert hashlib.sha256(data).hexdigest()==sha
root=pathlib.Path('/root/nlos_stage2/hybrid_fista_20261031');root.mkdir(parents=True,exist_ok=True)
p=root/'penumbra_gram.ko'
if p.exists():assert hashlib.sha256(p.read_bytes()).hexdigest()==sha,'Refuse to overwrite different module'
else:p.write_bytes(data)
if not pathlib.Path('/sys/module/penumbra_gram').exists():
 result=subprocess.run(['insmod',str(p)],stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
 print('INSMOD',result.returncode,result.stdout.decode(errors='replace'),flush=True)
 if result.returncode:print(subprocess.check_output(['dmesg']).decode(errors='replace')[-4000:]);raise RuntimeError('Module load rejected; not forced')
fd=os.open('/dev/penumbra_gram',os.O_RDWR|os.O_SYNC)
try:
 info=bytearray(16);fcntl.ioctl(fd,0x80104801,info,True);addr,size=struct.unpack('<QQ',info)
 assert size==16*1024*1024 and addr%4096==0 and addr+size<=2**32
 m=mmap.mmap(fd,size,flags=mmap.MAP_SHARED,prot=mmap.PROT_READ|mmap.PROT_WRITE)
 try:
  pattern=bytes(range(256))*16;m[:4096]=pattern;assert m[:4096]==pattern
  m[:4096]=b'\0'*4096;fcntl.ioctl(fd,0x4802)
 finally:m.close()
finally:os.close(fd)
report={'scope':'physical driver allocation only; no FPGA kernel access','driver_sha256':sha,'dma_address':hex(addr),'bytes':size,'readback_pass':True}
(root/'driver_validation.json').write_text(json.dumps(report,indent=2));print(json.dumps(report),flush=True)
print('[PASS PHYSICAL DMA BUFFER] 16 MiB allocated, 4096 bytes exact readback; FPGA not accessed',flush=True)
try:
 import numpy as np;print('BOARD_NUMPY',np.__version__)
except ImportError:print('BOARD_NUMPY_MISSING')

print(subprocess.check_output(['ip','-4','addr','show','eth0']).decode())
print('ETH0_CARRIER',pathlib.Path('/sys/class/net/eth0/carrier').read_text().strip())
